var output=new LabPinMap(activeLow:true);
var correct=new LabPinMap(activeLow:true);
var wrong=new LabPinMap(activeLow:false);
bool pressedHigh=output.LevelHigh(true);
bool releasedHigh=output.LevelHigh(false);
Console.WriteLine($"{pressedHigh}/{releasedHigh}"); // False/True
Console.WriteLine($"{correct.Decode(pressedHigh)}/{correct.Decode(releasedHigh)}"); // True/False
Console.WriteLine($"{wrong.Decode(pressedHigh)}/{wrong.Decode(releasedHigh)}"); // False/True
